machine_start_gcode:
; FELIX Food Switch - OrcaSlicer Start G-code - V1.00
{if bed_temperature_initial_layer_single>0}M190 S[bed_temperature_initial_layer_single]
{endif}T0
{if nozzle_temperature[1]>0}M104 T1 S{nozzle_temperature[1]}
{endif}{if nozzle_temperature[0]>0}M104 T0 S{nozzle_temperature[0]}
{endif}G28
G90
M82
M107
; ============== Prime second nozzle =============
{if is_extruder_used[1]}T1{else}T0{endif}
G1 X70 Y10 Z10 F{travel_speed*60} S1
M400
G92 E0
G1 E{2*retraction_length[1]+retract_restart_extra[1]+0.5} F15
G92 E0
G1 X{80+nozzle_diameter[1]*2} Y10 Z{nozzle_diameter[1]*0.5} F{travel_speed*60}
G1 X{100+nozzle_diameter[1]*2} Y10 E{nozzle_diameter[1]*initial_layer_print_height*20/((filament_diameter[1]/2)*(filament_diameter[1]/2)*3.14159)} F{initial_layer_speed*60}
G92 E0
G1 E-{retract_length_toolchange[1]} F{retraction_speed[1]*60}
G92 E0
; ============== Prime first nozzle ==============
T0
G1 X70 Y20 Z10 F{travel_speed*60}
M400
G92 E0
G1 E{2*retraction_length[0]+retract_restart_extra[0]+0.5} F15
G92 E0
G1 X{80+nozzle_diameter[0]*2} Y10 Z{nozzle_diameter[0]*0.5} F{travel_speed*60}
G1 X{100+nozzle_diameter[0]*2} Y10 E{nozzle_diameter[0]*initial_layer_print_height*20/((filament_diameter[0]/2)*(filament_diameter[0]/2)*3.14159)} F{initial_layer_speed*60}
G92 E0
G1 E-{retract_length_toolchange[0]} F{retraction_speed[0]*60}
G92 E0
